package com.finflow.payment; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="payments") class Payment{@Id UUID id;String idempotencyKey;String requestHash;UUID sourceAccountId;UUID destinationAccountId;BigDecimal amount;String currency;String status;String failureReason;String correlationId;@Version long version;Instant createdAt;Instant updatedAt;protected Payment(){} static Payment create(String key,String hash,UUID s,UUID d,BigDecimal a,String c,String corr){var p=new Payment();p.id=UUID.randomUUID();p.idempotencyKey=key;p.requestHash=hash;p.sourceAccountId=s;p.destinationAccountId=d;p.amount=a;p.currency=c;p.status="INITIATED";p.correlationId=corr;p.createdAt=p.updatedAt=Instant.now();return p;}void status(String s){status=s;updatedAt=Instant.now();}}